import sys

def longestPalin(S: str) -> str:
    n = len(S)
    if n == 0:
        return ""

    start = 0
    max_len = 1

    def expand_around_center(left: int, right: int) -> tuple:
        while left >= 0 and right < n and S[left] == S[right]:
            left -= 1
            right += 1
        return left + 1, right - left - 1

    for i in range(n):
        l1, r1 = expand_around_center(i, i)
        if r1 - l1 + 1 > max_len:
            max_len = r1 - l1 + 1
            start = l1

        l2, r2 = expand_around_center(i, i + 1)
        if r2 - l2 + 1 > max_len:
            max_len = r2 - l2 + 1
            start = l2

    return S[start:start + max_len]

if __name__ == "__main__":
    s_input = sys.stdin.read().strip()
    result = longestPalin(s_input)
    print(result)
